public interface PaymentMethod {
    String name();
    void pay(BigDecimal amount);
}
public class PaymentEngine {
    private final Map<String, PaymentMethod> map = new ConcurrentHashMap<>();
    public void register(PaymentMethod m) {
        map.put(m.name(), m);
    }
    public void execute(String name, BigDecimal amount) {
        map.get(name).pay(amount);
    }
}

