public interface AccountRepository {
    Account findById(String id);
    void save(Account account);
}
public class TransferFundsUseCase {
    private final AccountRepository repo;
    public TransferFundsUseCase(AccountRepository repo) { this.repo = repo; }
    public void transfer(String from, String to, BigDecimal amt) {
        Account a = repo.findById(from); Account b = repo.findById(to);
        a.debit(amt); b.credit(amt);
        repo.save(a); repo.save(b);
    }
}

